## 两种重构方案

### 方案 A（推荐）：提取 `rollbackSingleFile`，让 `undo` 和 `undoFile` 共享

把"单文件的回滚执行"抽成一个私有方法，两个方法都调用它：

```typescript
/**
 * 回滚单个文件到快照前的状态
 * @returns 回滚结果条目，不成功返回 null
 */
private async rollbackSingleFile(
  filePath: string,
  file: SnapshotFile,
  snapshotId: string,
): Promise<{ filePath: string; action: "restored" | "deleted" } | null> {
  const log = getLogger();

  if (!file.existedBefore) {
    // 新创建的文件：删除
    if (!existsSync(filePath)) return null;
    try {
      unlinkSync(filePath);
      log.info("CHECKPOINT", `已删除新文件: ${filePath}`);
      return { filePath, action: "deleted" };
    } catch (err: any) {
      log.warn("CHECKPOINT", `删除文件失败: ${filePath} - ${err.message}`);
      return null;
    }
  }

  // 已有文件：恢复到快照前的内容
  const content = await this.rebuildContentBeforeSnapshot(filePath, snapshotId);
  if (content === null) return null;

  try {
    await Bun.write(filePath, content);
    log.info("CHECKPOINT", `已恢复文件: ${filePath}`);
    return { filePath, action: "restored" };
  } catch (err: any) {
    log.warn("CHECKPOINT", `恢复文件失败: ${filePath} - ${err.message}`);
    return null;
  }
}
```

